// Writes styles.css. Obsidian loads it itself; plugins may not create
// <style> elements. Each highlight style Treelights uses at runtime gets a
// numbered slot (.tl-0, .tl-1, ...); the plugin sets only the slot's CSS
// variables (with Obsidian's setCssProps), and these rules apply them.
// A session uses about 35 styles; 256 slots leave plenty of room.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

export const SLOTS = 256;
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const out = [
  "/* Generated by tools/gen-styles.mjs. Do not edit. */",
  "",
  "/* Settings: the three security toggles sit under the master switch */",
  ".treelights-sub-setting { padding-inline-start: 2em; }",
  "/* The hidden file picker used by \"Import a Helix theme\" */",
  ".treelights-file-input { display: none; }",
  "",
  "/* Nested pieces inside a badge or chip draw no box of their own */",
  ".treelights-on .tl-chip span { background: none !important; box-shadow: none !important; padding: 0 !important; border-radius: 0 !important; }",
  "",
];
for (let i = 0; i < SLOTS; i++) {
  const v = (name) => `var(--tl-${i}-${name})`;
  out.push(
    `.treelights-on .tl-${i}, .treelights-on .tl-${i} span { color: ${v("c")} !important; font-weight: var(--tl-${i}-w, inherit) !important; font-style: var(--tl-${i}-s, normal) !important; text-decoration: var(--tl-${i}-d, inherit) !important; }`,
    `.treelights-on .tl-${i} { background: var(--tl-${i}-bg, none) !important; text-shadow: var(--tl-${i}-ts, none); border-radius: var(--tl-${i}-r, 0); padding: var(--tl-${i}-p, 0); box-shadow: var(--tl-${i}-sh, none); unicode-bidi: var(--tl-${i}-ub, normal); direction: var(--tl-${i}-dir, inherit); }`,
    `.treelights-on .tl-${i}::before { content: var(--tl-${i}-m, none); font-weight: bold; }`,
  );
}
fs.writeFileSync(path.join(root, "styles.css"), out.join("\n") + "\n");
console.log(`styles.css: ${SLOTS} style slots (${Math.round(fs.statSync(path.join(root, "styles.css")).size / 1024)} KB)`);
